<?php get_header(); $month=kzfr_filter_value('month'); $args=['meta_key'=>'kzfr_event_date','orderby'=>'meta_value','order'=>'ASC']; if(preg_match('/^\d{4}-\d{2}$/',$month)) $args['meta_query']=[['key'=>'kzfr_event_date','value'=>$month,'compare'=>'LIKE']]; $events=kzfr_query('kzfr_event',-1,$args); ?><div class="section-wrap section-space"><?php kzfr_page_intro('STATION EVENTS','Events','A preview of upcoming events listed on KZFR’s official website.'); ?><form class="filter-bar" method="get"><input type="hidden" name="design" value="<?php echo esc_attr(kzfr_current_design()); ?>"><div class="field"><label for="event-month">Month</label><input id="event-month" type="month" name="month" value="<?php echo esc_attr($month); ?>"></div><button class="button button-dark" type="submit">Filter events</button><a href="<?php echo kzfr_url('events'); ?>">Show all</a></form><div class="event-list"><?php while($events->have_posts()): $events->the_post(); kzfr_event_card(get_the_ID()); endwhile; wp_reset_postdata(); ?></div><?php if(!$events->found_posts): ?><div class="empty-state"><h2>No events in this preview for that month.</h2><p>Check <a href="https://www.kzfr.org/events">KZFR’s official calendar</a> for the latest listings.</p></div><?php endif; ?><aside class="source-note">Dates, availability, and admission details can change. Confirm with the official event listing before attending.</aside></div><?php get_footer(); ?>
